import base64
import gzip
import subprocess

PATCH_B64 = ""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
subprocess.run(
    ["git", "apply", "--ignore-space-change", "--ignore-whitespace", "--whitespace=nowarn", "-"],
    input=patch,
    check=True,
)
print("v2.0.9 fresh-chat generation handoff patch applied")
